export const DUNYA: DunyaUlkesi[] = HAM.map(([kod, ad, x, y, yol]) => ({
  kod,
  ad,
  merkez: [x, y],
  yol,
}))

/** Koddan ülke; havuz yalnızca kodu saklıyor. */
export function ulkeBul(kod: string): DunyaUlkesi | undefined {
  return DUNYA.find((u) => u.kod === kod)
}
